// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_fallbackAcceptsUnknownCalldata(uint96 amount, bytes4 sel) public {
        vm.assume(amount > 0);
        vm.assume(sel != bytes4(keccak256("owner()")));
        vm.assume(sel != bytes4(keccak256("depositsCount()")));
        vm.assume(sel != bytes4(keccak256("withdrawAll()")));
        vm.assume(sel != bytes4(keccak256("withdraw(uint256)")));
        vm.assume(sel != bytes4(keccak256("sendMoney(address,uint256)")));
        vm.deal(address(this), amount);
        uint256 depBefore = c.depositsCount();
        uint256 balBefore = address(c).balance;
        (bool ok, ) = address(c).call{value: amount}(abi.encodePacked(sel));
        assertTrue(ok);
        assertEq(c.depositsCount(), depBefore + 1);
        assertEq(address(c).balance, balBefore + amount);
    }
}
